package pascal

import (
	"reflect"
	"testing"
)

func TestPascalZero(t *testing.T) {
	if got := PascalTriangle(0); len(got) != 0 {
		t.Errorf("PascalTriangle(0) = %v, want []", got)
	}
}

func TestPascalOne(t *testing.T) {
	got := PascalTriangle(1)
	want := [][]int{{1}}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("PascalTriangle(1) = %v, want %v", got, want)
	}
}

func TestPascalFour(t *testing.T) {
	got := PascalTriangle(4)
	want := [][]int{{1}, {1, 1}, {1, 2, 1}, {1, 3, 3, 1}}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("PascalTriangle(4) = %v, want %v", got, want)
	}
}

func TestPascalFifthRow(t *testing.T) {
	rows := PascalTriangle(5)
	want := []int{1, 4, 6, 4, 1}
	if !reflect.DeepEqual(rows[4], want) {
		t.Errorf("row 5 = %v, want %v", rows[4], want)
	}
}
